import{ActionRowBuilder as l,ButtonBuilder as o,ButtonStyle as s,PermissionsBitField as i,SlashCommandBuilder as c,MessageFlags as r}from"discord.js";var n=class{enabled=!0;commandName="command_console";commandDescription="Creates a row of buttons which execute commands";async createSlashCommand(){return new c().setName(this.commandName).setDescription(this.commandDescription).setDefaultMemberPermissions(i.Flags.ManageMessages)}async createCommandFunctionality(){return async e=>{let a=new l().addComponents(new o().setCustomId("reload_all").setLabel("Reload").setStyle(s.Primary),new o().setCustomId("whitelist").setLabel("Whitelist").setStyle(s.Primary));return await e.reply({content:"Command console:",components:[a]})}}async handleButton(e){if(e.customId==="reload_all"){let t=e.client.commands.get("reload_all");if(t)try{await t.execute(e)}catch(m){console.error(m),await e.followUp({content:"There was an error while executing the reload command!",flags:[r.Ephemeral]})}}if(e.customId==="whitelist"){let t=e.client.commands.get("whitelist");t&&t.handleButton&&await t.handleButton(e)}}async createObject(){return{data:await this.createSlashCommand(),execute:await this.createCommandFunctionality(),handleButton:this.handleButton.bind(this)}}};export{n as default};
